const options=mysql.config(process.env,'TEST_MYSQL_'),samples={},operations={},als=new AsyncLocalStorage();let sqlCount=0,rowsReturned=0;
const observe=(stage,ms,detail)=>{(samples[stage]??=[]).push(ms);const ctx=als.getStore();if(stage.startsWith('sql:')){sqlCount++;rowsReturned+=detail?.rows||0;if(ctx&&!ctx.closed){ctx.sqlCount++;ctx.sqlMs+=ms;ctx.rows+=detail?.rows||0;}}if(ctx&&!ctx.closed&&(stage==='authentication'||stage==='handler'))ctx[stage]+=ms;};
