const loop=monitorEventLoopDelay({resolution:20});loop.enable();let peakRss=0,peakHeap=0;const started=performance.now(),cpuStart=process.cpuUsage(),sampler=setInterval(()=>{const m=process.memoryUsage();peakRss=Math.max(peakRss,m.rss);peakHeap=Math.max(peakHeap,m.heapUsed);},100);sampler.unref();
